<?php
if (!defined('ABSPATH')) exit;
final class ULD_V4_AI_Lesson_Builder {
 public static function init(){add_action('admin_menu',[__CLASS__,'menu'],110);add_action('admin_init',[__CLASS__,'actions'],8);}
 public static function menu(){add_submenu_page('uld','AI Lesson Builder','AI Lesson Builder','manage_options','uld-ai-lesson-builder',[__CLASS__,'page']);}
 private static function provider(){return class_exists('ULD_V4_AI_Providers')?ULD_V4_AI_Providers::provider():'openai';}
 private static function key(){return class_exists('ULD_V4_AI_Providers')?ULD_V4_AI_Providers::key():trim((string)get_option('uld_ai_api_key'));}
 private static function model(){return class_exists('ULD_V4_AI_Providers')?ULD_V4_AI_Providers::model():trim((string)get_option('uld_ai_model','gpt-5-mini'));}
 public static function actions(){if(!is_admin()||!current_user_can('manage_options')||empty($_POST['uld_ai_generate_lesson']))return;check_admin_referer('uld_ai_generate_lesson');$source=wp_kses_post(wp_unslash($_POST['source_content']??''));if(trim(wp_strip_all_tags($source))===''){wp_safe_redirect(admin_url('admin.php?page=uld-ai-lesson-builder&uld_error=missing_content'));exit;}$result=self::generate($source,['title'=>sanitize_text_field(wp_unslash($_POST['lesson_title']??'')),'level'=>sanitize_text_field(wp_unslash($_POST['audience_level']??'Intermediate')),'length'=>sanitize_text_field(wp_unslash($_POST['lesson_length']??'Standard')),'tone'=>sanitize_text_field(wp_unslash($_POST['teaching_tone']??'Academic and practical')),'quiz'=>!empty($_POST['include_quiz'])]);if(is_wp_error($result)){set_transient('uld_ai_error_'.get_current_user_id(),$result->get_error_message(),600);wp_safe_redirect(admin_url('admin.php?page=uld-ai-lesson-builder&uld_error=generation_failed'));exit;}$post_id=wp_insert_post(['post_type'=>'uld_lesson','post_status'=>sanitize_key($_POST['save_mode']??'draft')==='publish'?'publish':'draft','post_title'=>sanitize_text_field($result['title']??'AI Lesson'),'post_content'=>wp_kses_post($result['html']??'')]);if(!$post_id||is_wp_error($post_id)){wp_safe_redirect(admin_url('admin.php?page=uld-ai-lesson-builder&uld_error=save_failed'));exit;}$cid=absint($_POST['course_id']??0);if($cid&&get_post_type($cid)==='uld_course')update_post_meta($post_id,'uld_course_id',$cid);update_post_meta($post_id,'uld_ai_generated',1);update_post_meta($post_id,'uld_ai_provider',self::provider());if(!empty($_POST['auto_sync_drive']))update_post_meta($post_id,'uld_auto_sync',1);wp_safe_redirect(add_query_arg(['post'=>$post_id,'action'=>'edit','uld_notice'=>'ai_created'],admin_url('post.php')));exit;}
 private static function prompt($source,$o){$quiz=$o['quiz']?'Include a 5-question knowledge check with answers.':'Do not include a quiz.';return "Convert the supplied teacher content into a polished academic LMS lesson. Audience: {$o['level']}. Depth: {$o['length']}. Style: {$o['tone']}. Include overview, 3-6 measurable objectives, clear instructional sections, explanations, practical examples, key terms, recap and next steps. {$quiz} Preserve source meaning and do not invent unsupported facts. Return ONLY valid JSON with keys title and html. HTML may use h2,h3,p,ul,ol,li,strong,em,blockquote,table. Preferred title: {$o['title']}\n\nSOURCE:\n".wp_strip_all_tags($source);}
 private static function generate($source,$o){$key=self::key();if(!$key)return new WP_Error('no_key','Configure an AI provider under UWEBBZ Drive → AI Providers first.');$p=self::provider();$prompt=self::prompt($source,$o);if($p==='gemini'){$url='https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode(self::model()).':generateContent?key='.rawurlencode($key);$r=wp_remote_post($url,['timeout'=>90,'headers'=>['Content-Type'=>'application/json'],'body'=>wp_json_encode(['contents'=>[['parts'=>[['text'=>$prompt]]]]])]);$b=json_decode(wp_remote_retrieve_body($r),true);$text=$b['candidates'][0]['content']['parts'][0]['text']??'';}elseif($p==='claude'){$r=wp_remote_post('https://api.anthropic.com/v1/messages',['timeout'=>90,'headers'=>['x-api-key'=>$key,'anthropic-version'=>'2023-06-01','Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>self::model(),'max_tokens'=>7000,'messages'=>[['role'=>'user','content'=>$prompt]]])]);$b=json_decode(wp_remote_retrieve_body($r),true);$text=$b['content'][0]['text']??'';}else{$r=wp_remote_post('https://api.openai.com/v1/responses',['timeout'=>90,'headers'=>['Authorization'=>'Bearer '.$key,'Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>self::model(),'input'=>$prompt])]);$b=json_decode(wp_remote_retrieve_body($r),true);$text='';foreach((array)($b['output']??[])as$item)foreach((array)($item['content']??[])as$part)if(isset($part['text']))$text.=$part['text'];}if(is_wp_error($r))return$r;$code=wp_remote_retrieve_response_code($r);if($code<200||$code>=300)return new WP_Error('ai_api',$b['error']['message']??'AI request failed.');$text=trim($text);if(str_starts_with($text,'```'))$text=preg_replace('/^```(?:json)?\s*|\s*```$/','',$text);$d=json_decode($text,true);return(is_array($d)&&!empty($d['html']))?$d:new WP_Error('bad_output','The AI response could not be converted into a lesson.');}
 public static function page(){$ready=(bool)self::key();$p=self::provider();$courses=get_posts(['post_type'=>'uld_course','post_status'=>['publish','draft'],'numberposts'=>-1,'orderby'=>'title','order'=>'ASC']);echo '<div class="wrap uld-wrap"><div class="uld-hero"><div><span class="uld-kicker">UWEBBZ AI STUDIO</span><h1>AI Lesson Builder</h1><p>Paste your teaching content and turn it into a structured lesson. AI credentials are managed separately.</p></div><div class="uld-status '.($ready?'is-connected':'is-offline').'"><span class="uld-dot"></span>'.esc_html($ready?ucfirst($p).' Ready':'AI Setup Required').'</div></div>';if(!$ready)echo '<div class="notice notice-warning"><p>AI is not configured yet. <a href="'.esc_url(admin_url('admin.php?page=uld-ai-providers')).'">Configure AI Providers</a>.</p></div>';if(isset($_GET['uld_error'])){$e=get_transient('uld_ai_error_'.get_current_user_id());echo '<div class="notice notice-error"><p>'.esc_html($e?:'AI generation failed.').'</p></div>';}echo '<form method="post">';wp_nonce_field('uld_ai_generate_lesson');echo '<section class="uld-v4-panel"><h2>1. Add Your Content</h2><textarea class="uld-ai-source" name="source_content" rows="18" placeholder="Paste chapter, notes, outline, SOP, lecture material, or other content..." required></textarea><div class="uld-v4-field"><label>Preferred lesson title</label><input type="text" name="lesson_title" placeholder="AI can create one automatically"></div><h3>Audience</h3><div class="uld-v4-tabs"><label><input type="radio" name="audience_level" value="Beginner"><span>Beginner</span></label><label><input type="radio" name="audience_level" value="Intermediate" checked><span>Intermediate</span></label><label><input type="radio" name="audience_level" value="Advanced"><span>Advanced</span></label></div><h3>Depth</h3><div class="uld-v4-tabs"><label><input type="radio" name="lesson_length" value="Concise"><span>Concise</span></label><label><input type="radio" name="lesson_length" value="Standard" checked><span>Standard</span></label><label><input type="radio" name="lesson_length" value="Deep academic"><span>Deep Academic</span></label></div><input type="hidden" name="teaching_tone" value="Academic, practical, clear, and instructor-led"></section><section class="uld-v4-panel"><h2>2. Choose Course</h2><div class="uld-v4-course-grid"><label class="uld-v4-course-card"><input type="radio" name="course_id" value="0" checked><span class="dashicons dashicons-media-document"></span><span><strong>Unassigned</strong><small>Assign later</small></span></label>';foreach($courses as$c)echo '<label class="uld-v4-course-card"><input type="radio" name="course_id" value="'.absint($c->ID).'"><span class="dashicons dashicons-welcome-learn-more"></span><span><strong>'.esc_html($c->post_title).'</strong><small>Course</small></span></label>';echo '</div><div class="uld-ai-switches"><label><input type="checkbox" name="include_quiz" value="1" checked> Include knowledge check</label><label><input type="checkbox" name="auto_sync_drive" value="1"> Auto-sync to Google Drive</label></div><div class="uld-v4-tabs"><label><input type="radio" name="save_mode" value="draft" checked><span>Save Draft</span></label><label><input type="radio" name="save_mode" value="publish"><span>Publish</span></label></div><p><button class="button button-primary button-hero" name="uld_ai_generate_lesson" value="1" '.disabled(!$ready,true,false).'>✨ Generate Lesson with AI</button> <a class="button" href="'.esc_url(admin_url('admin.php?page=uld-ai-providers')).'">AI Settings</a></p></section></form></div>';}
}
ULD_V4_AI_Lesson_Builder::init();
